 using System.IO;
 using ABLogixGitManager.Services;
 using ABLogixGitManager.Views;

 namespace ABLogixGitManager;

 /// <summary>
 /// Application entry point. Registers global exception handlers, initialises the
 /// logger, and triggers the first-run Settings window when l5xgit is not yet configured.
 /// </summary>
 public partial class App : Application
 {
     private readonly CrashRecoveryService _crashRecoveryService = new();

     /// <inheritdoc/>
     protected override void OnStartup(StartupEventArgs e)
     {
         base.OnStartup(e);

         RegisterUnhandledExceptionHandlers();
         AppLogger.Info($"Application starting. Log file: {AppLogger.FilePath}");

         var previousRunCrash = _crashRecoveryService.BeginSession();
         if (previousRunCrash is not null)
         {
             AppLogger.Warn("Previous session did not exit cleanly. Scheduling crash-recovery notification.");
             RunOnFirstActivation(() =>
             {
                 MessageBox.Show(
                     MainWindow,
                     BuildPreviousCrashMessage(previousRunCrash),
                     "Previous Run Ended Unexpectedly",
                     MessageBoxButton.OK,
                     MessageBoxImage.Warning);
             });
         }

         // Open the Settings window on first run so users know what to configure.
         // "First run" is defined as: l5xgit.exe path has never been saved.
         var config = new AppConfigService().Load();
         var appliedTheme = AppThemeService.ApplyConfiguredTheme(config.Theme);
         AppLogger.Info($"Applied fixed application theme: {appliedTheme}.");
         if (string.IsNullOrWhiteSpace(config.L5xGitExePath))
         {
             AppLogger.Info("First run detected — l5xgit path not configured. Scheduling Settings window.");
             RunOnFirstActivation(() =>
             {
                 AppLogger.Info("Opening Settings window for first-run configuration.");
                 new SettingsWindow(string.Empty) { Owner = MainWindow }.ShowDialog();
             });
         }
     }

     /// <inheritdoc/>
     protected override void OnExit(ExitEventArgs e)
     {
         _crashRecoveryService.MarkCleanShutdown();
         AppLogger.Info($"Application exiting with code {e.ApplicationExitCode}.");
         base.OnExit(e);
     }

     // -------------------------------------------------------------------------
     // Global exception handlers
     // -------------------------------------------------------------------------

     /// <summary>
     /// Registers three complementary unhandled exception handlers so that any
     /// crash — whether on the UI thread, a background thread, or an async task —
     /// is written to the log file before the process terminates.
     /// </summary>
     private void RegisterUnhandledExceptionHandlers()
     {
         // WPF dispatcher exceptions (UI thread): log and show a user-friendly message.
         DispatcherUnhandledException += OnDispatcherUnhandledException;

         // CLR domain exceptions (any non-UI thread): log only; process is about to terminate.
         AppDomain.CurrentDomain.UnhandledException += OnDomainUnhandledException;

         // Unobserved async task exceptions: log and prevent automatic process termination.
         TaskScheduler.UnobservedTaskException += OnUnobservedTaskException;
     }

     private void OnDispatcherUnhandledException(object sender, DispatcherUnhandledExceptionEventArgs args)
     {
         _crashRecoveryService.RecordUnhandledException("dispatcher", args.Exception);
         AppLogger.Error("Unhandled dispatcher exception", args.Exception);
         MessageBox.Show(
             $"An unexpected error occurred:\n\n{args.Exception.Message}\n\n" +
             $"Details have been written to:\n{AppLogger.FilePath}",
             "Unexpected Error",
             MessageBoxButton.OK,
             MessageBoxImage.Error);

         // Mark as handled so WPF does not terminate the process; the user can
         // continue if the application state is still consistent.
         args.Handled = true;
     }

     private static void OnDomainUnhandledException(object sender, UnhandledExceptionEventArgs args)
     {
         var ex = args.ExceptionObject as Exception;
         if (Current is App app)
             app._crashRecoveryService.RecordUnhandledException("domain", ex);

         AppLogger.Error(
             $"Unhandled domain exception (terminating={args.IsTerminating})",
             ex);
     }

     private static void OnUnobservedTaskException(object? sender, UnobservedTaskExceptionEventArgs args)
     {
         if (Current is App app)
             app._crashRecoveryService.RecordUnhandledException("task", args.Exception);

         AppLogger.Error("Unobserved task exception", args.Exception);
         // Prevent .NET from re-throwing the exception and crashing the process.
         args.SetObserved();
     }

     private void RunOnFirstActivation(Action action)
     {
         EventHandler? handler = null;
         handler = (_, _) =>
         {
             Activated -= handler;
             action();
         };
         Activated += handler;
     }

     private static string BuildPreviousCrashMessage(PreviousRunCrashInfo previousRunCrash)
     {
         var details = previousRunCrash.CrashDetectedUtc is DateTimeOffset crashUtc
             ? $"Unhandled exception captured at {crashUtc.LocalDateTime:G} ({previousRunCrash.CrashSource ?? "unknown source"})."
             : "The app did not shut down cleanly (possible freeze, forced close, or crash).";

         var summary = !string.IsNullOrWhiteSpace(previousRunCrash.ExceptionMessage)
             ? $"{previousRunCrash.ExceptionType}: {previousRunCrash.ExceptionMessage}"
             : "No exception details were captured before shutdown.";

         var logPath = string.IsNullOrWhiteSpace(previousRunCrash.LastKnownLogPath)
             ? AppLogger.FilePath
             : previousRunCrash.LastKnownLogPath;
         var logTail = TryReadLogTail(logPath);

         return
             $"AB Logix Git Manager detected that the previous run ended unexpectedly.\n\n" +
             $"{details}\n\n" +
             $"Summary: {summary}\n\n" +
             $"Please send this log file to support:\n{logPath}\n\n" +
             $"Recent log output:\n{logTail}";
     }

     private static string TryReadLogTail(string logPath, int maxLines = 20)
     {
         try
         {
             if (!File.Exists(logPath))
                 return "(log file not found)";

             var lines = File.ReadAllLines(logPath);
             var tailLines = lines.Length <= maxLines ? lines : lines[^maxLines..];
             return string.Join(Environment.NewLine, tailLines);
         }
         catch (Exception ex)
         {
             return $"(failed to read log file: {ex.Message})";
         }
     }
